function V3_now(){return new Date().toISOString()}
function V3_labelStatus(v){return v==='New'?t('newStatus'):v==='In progress'?t('progress'):v==='Ready for review'?t('readyStatus'):v==='Rejected'?t('rejectedStatus'):t('resolved')}
function V3_statusChip(v){let kind=v==='Resolved'?'green':v==='Rejected'?'red':v==='Ready for review'?'blue':v==='In progress'?'amber':'red';return `<span class="chip ${kind}">${esc(V3_labelStatus(v))}</span>`}
function V3_verifyLabel(r){return r.verification==='verified'?t('verifyApproved'):r.verification==='rejected'?t('verifyRejected'):t('verifyPending')}
function V3_verificationChip(r){return `<span class="chip ${r.verification==='verified'?'green':r.verification==='rejected'?'red':'amber'}">${esc(V3_verifyLabel(r))}</span>`}
function V3_event(type,actor,notes=''){return{type,actor,notes,at:V3_now()}}
function V3_sample(id,category,loc,status,verification,team,description,urgency='medium'){const stamp=Date.now();const older=stamp-((id==='EA-3102'?55:15)*60*1000);const hist=[{type:'timelineSubmitted',actor:'Attendee',notes:'Example report generated for demonstration.',at:new Date(older).toISOString()}];if(verification==='verified')hist.push({type:'timelineVerified',actor:'Organiser',notes:'Demo site information reviewed.',at:new Date(older+5*60000).toISOString()});if(verification==='rejected')hist.push({type:'timelineRejected',actor:'Organiser',notes:'Demo report not substantiated.',at:new Date(older+5*60000).toISOString()});if(team!=='Unassigned'&&verification==='verified')hist.push({type:'timelineAssigned',actor:'Organiser',notes:team,at:new Date(older+10*60000).toISOString()});if(status==='In progress')hist.push({type:'timelineStarted',actor:'Staff',notes:'Demo work under way.',at:new Date(older+12*60000).toISOString()});if(status==='Resolved'){hist.push({type:'timelineCompleted',actor:'Staff',notes:'Demo obstruction removed.',at:new Date(older+20*60000).toISOString()});hist.push({type:'timelineResolved',actor:'Organiser',notes:'Example area restored.',at:new Date(older+25*60000).toISOString()})}return{id,category,loc,status,verification,team,details:description,urgency,notes:'',photo:'',created:hist[0].at,updated:hist[hist.length-1].at,history:hist}}
