function V3_activeVerified(){return reports.filter(r=>r.verification==='verified'&&!['Resolved','Rejected'].includes(r.status))}
function V3_closedFacility(id){return V3_activeVerified().some(r=>(r.category==='liftbroken'&&(r.loc==='lift'||r.loc==='upperLift')&&(id==='lift'||id==='upperLift'))||(r.category==='toiletbroken'&&r.loc===id))}
closedFacility=V3_closedFacility;
function V3_blockedEdges(){let out=new Set();for(const r of V3_activeVerified())if(r.category==='blocked'){
 const pairs={eastcorridor:['firstaid','toilet'],westcorridor:['registration','crosswest'],maincorridor:['crossMid','crossEast'],registration:['registration','crosswest'],firstaid:['firstaid','toilet'],toilet:['firstaid','toilet'],hall:['crossMid','hall'],entrance:['entrance','registration'],lift:['crossEast','lift'],prayer:['crossQuiet','prayer'],quiet:['crossQuiet','quiet'],studio:['upperLobby','studio'],lounge:['upperLobby','lounge'],toilet1:['lounge','toilet1'],upperLift:['upperLift','upperLobby'],upperLobby:['upperLift','upperLobby']};if(pairs[r.loc])out.add(edgeKey(...pairs[r.loc]));}
 return out}
blockedEdges=V3_blockedEdges;
function V3_shortest(a,b,avoid=true){if(a===b||!nodes[a]||!nodes[b]||(avoid&&V3_closedFacility(b)))return null;const blocked=avoid?V3_blockedEdges():new Set();const vertices=new Set(Object.keys(nodes)),dist={},prev={};for(const id of vertices)dist[id]=Infinity;dist[a]=0;while(vertices.size){let u=[...vertices].reduce((p,q)=>dist[p]<dist[q]?p:q);vertices.delete(u);if(!isFinite(dist[u]))break;if(u===b)break;for(const [m,n]of networkEdges){if(m!==u&&n!==u)continue;const v=m===u?n:m;if(!vertices.has(v)||blocked.has(edgeKey(m,n)))continue;if(avoid&&(V3_closedFacility(v)||V3_closedFacility(u)))continue;const weight=(edgeKey(m,n)===edgeKey('lift','upperLift'))?145:Math.hypot(nodes[u][0]-nodes[v][0],nodes[u][1]-nodes[v][1]);if(dist[u]+weight<dist[v]){dist[v]=dist[u]+weight;prev[v]=u}}}if(!isFinite(dist[b]))return null;let path=[b];while(path[0]!==a){path.unshift(prev[path[0]]);if(path.length>35)return null}return{path,units:dist[b],distance:Math.round(dist[b]*.13),minutes:Math.max(1,Math.ceil(dist[b]*.13/45)),changesFloor:path.includes('upperLift')&&path.includes('lift'),floorPaths:{G:path.filter(id=>V3_LOCATION_FLOOR(id)==='G'),L1:path.filter(id=>V3_LOCATION_FLOOR(id)==='L1')}}}
shortest=V3_shortest;
