function V3_markerIcon(id,index=0){
 const drawing=V3_PIN_DRAWINGS[id]||V3_PIN_DRAWINGS.upperLobby;
 return `<svg class="pin-pictogram pin-pictogram-${id}" x="-13" y="-13" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="--pin-sequence:${index%5}">${drawing}</svg>`;
}
function V3_floorMap(floor,route=null,editable=true){const upper=floor==='L1';const rooms=upper?`<rect class="zoneb" x="95" y="175" width="220" height="250" rx="14"/><rect class="zone" x="590" y="55" width="285" height="200" rx="14"/><rect class="zonep" x="590" y="355" width="285" height="205" rx="14"/><rect class="zoneg" x="882" y="355" width="170" height="205" rx="14"/><text class="zlabel" x="118" y="223">LIFT A LOBBY</text><text class="zlabel" x="648" y="115">WORKSHOP STUDIO</text><text class="zlabel" x="663" y="407">CONFERENCE LOUNGE</text><text class="zsmall" x="911" y="415">ACCESSIBLE</text><text class="zsmall" x="911" y="434">TOILET</text>`:
 `<rect class="zone" x="353" y="65" width="212" height="168" rx="13"/><rect class="zoneb" x="684" y="64" width="180" height="157" rx="13"/><rect class="zonep" x="883" y="64" width="157" height="157" rx="13"/><rect class="zoneg" x="204" y="538" width="348" height="52" rx="11"/><rect class="zone" x="692" y="536" width="178" height="55" rx="11"/><rect class="zonep" x="887" y="536" width="153" height="55" rx="11"/><rect class="zone" x="80" y="396" width="120" height="72" rx="11"/><text class="zlabel" x="382" y="128">MAIN EVENT HALL</text><text class="zsmall" x="410" y="151">Programme space</text><text class="zlabel" x="726" y="108">LIFT LOBBY</text><text class="zsmall" x="738" y="135">Lift A</text><text class="zlabel" x="903" y="107">QUIET ROOM</text><text class="zsmall" x="260" y="566">REGISTRATION / CHECK-IN</text><text class="zsmall" x="715" y="567">ACCESSIBLE TOILET</text><text class="zsmall" x="915" y="567">PRAYER ROOM</text>`;
 const edges=networkEdges.filter(([a,b])=>V3_LOCATION_FLOOR(a)===floor&&V3_LOCATION_FLOOR(b)===floor).map(([a,b])=>`M${nodes[a].join(' ')} L${nodes[b].join(' ')}`).join(' ');
 const closures=[...V3_blockedEdges()].map(edge=>{let [a,b]=edge.split('|');if(!nodes[a]||V3_LOCATION_FLOOR(a)!==floor||V3_LOCATION_FLOOR(b)!==floor)return'';return `<path class="blocked" d="M${nodes[a].join(' ')} L${nodes[b].join(' ')}"/>`}).join('');
 const marks=Object.entries(facility).filter(([id])=>V3_LOCATION_FLOOR(id)===floor).map(([id,f])=>{const pending=reports.some(r=>r.loc===id&&r.verification==='pending'&&r.status!=='Resolved');const active=V3_activeVerified().some(r=>r.loc===id);const off=closedFacility(id);const current=V3_qr===id;return `<g class="pin ${chosen===id?'active':''} ${off||active?'issue':''} ${categoryFilter!=='all'&&f.cat!==categoryFilter?'faded':''}" transform="translate(${f.x} ${f.y})" ${editable?`role="button" tabindex="0" aria-label="${esc(V3_labelLoc(id))}" onclick="chooseFacility('${id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseFacility('${id}')}"`:''}><title>${esc(V3_labelLoc(id))}</title><circle r="21"/>${V3_markerIcon(id,Object.keys(facility).indexOf(id))}${pending?`<circle class="pending-halo" cx="22" cy="-21" r="6"/>`:''}${current?`<circle class="you-marker" cx="-23" cy="-23" r="10"/><text x="-23" y="-23" style="font-size:9px">●</text>`:''}</g>`}).join('');
const incidentMarks=upper?'':Object.entries(areas).map(([id,area])=>{const pending=reports.filter(r=>r.loc===id&&r.verification==='pending'&&r.status!=='Resolved').length;const confirmed=V3_activeVerified().filter(r=>r.loc===id).length;if(!pending&&!confirmed)return'';const color=confirmed?'#c75c4d':'#e2a44a';const title=confirmed?t('confirmedClosure'):t('mapReported');return `<g class="corridor-issue" role="img" aria-label="${esc(V3_labelLoc(id))}: ${esc(title)}"><circle cx="${area.x}" cy="${area.y-32}" r="17" fill="${color}" stroke="white" stroke-width="4"/><text x="${area.x}" y="${area.y-32}" text-anchor="middle" dominant-baseline="central" fill="white" font-weight="900" font-size="16">${confirmed?'!':'?'}</text></g>`}).join('');
return `<svg class="map-canvas" viewBox="0 0 1080 620" role="img" aria-label="Illustrative ${upper?'level one':'ground floor'} map with selectable accessibility markers and verified closure alerts"><rect x="1" y="1" width="1078" height="618" rx="15" fill="#f6faf9"/><g>${rooms}</g><g><path class="corridor" d="${edges}"/><path class="centerline" d="${edges}"/></g>${V3_routeLine(route,floor)}${closures}${incidentMarks}<g>${marks}</g><g transform="translate(1000 25)"><circle cx="24" cy="23" r="20" fill="white" stroke="#e0e9e5"/><path d="M24 8 18 29 24 26 30 29Z" fill="#508c7d"/><text x="24" y="58" text-anchor="middle" fill="#7e9694" font-size="11" font-weight="800">N</text></g></svg>`}
function V3_floorButtons(){return `<div class="floor-switch" role="group" aria-label="${t('floorSelect')}">${[['G','floorG'],['L1','floor1']].map(([id,name])=>`<button class="${V3_floor===id?'active':''}" onclick="V3_setFloor('${id}')">${esc(t(name))}</button>`).join('')}</div>`}
function V3_setFloor(floor){V3_floor=floor;const opts=Object.entries(facility).filter(([id,f])=>V3_LOCATION_FLOOR(id)===floor);if(!opts.some(([id])=>id===chosen))chosen=opts[0][0];render()}
function V3_facilityOptions(v){return Object.entries(facility).map(([id])=>`<option value="${id}" ${v===id?'selected':''}>${esc(V3_labelLoc(id))} · ${V3_floorName(id)}</option>`).join('')}
function V3_map(){const f=facility[chosen],isUpper=V3_LOCATION_FLOOR(chosen)==='L1';const locActive=V3_activeVerified().filter(r=>r.loc===chosen);const locPending=reports.filter(r=>r.loc===chosen&&r.verification==='pending'&&r.status!=='Resolved');return `${pageHead('mapTitle','mapSub')}<div class="v3-inline-feature">${ic('shield',18)} ${t('noticePending')}</div><div class="split"><section class="card map-panel"><div class="map-toolbar">${V3_floorButtons()}<span class="floor-pill">${ic('map',15)} ${t('floorSub')}</span></div><div class="map-toolbar">${filterButtons()}<span class="chip green">${ic('pin',12)} ${t('youHere')}: ${esc(V3_labelLoc(V3_qr))}</span></div>${V3_floorMap(V3_floor,null,true)}<div class="legend"><span><i></i>${t('greenPin')}</span><span><i class="hazard"></i>${t('confirmedClosure')}</span><span><i class="amber-dot"></i>${t('mapReported')}</span></div><p class="small-hint">${ic('info',15)} ${t('mapDisclaimer')} ${t('verifiedWarnings')}</p></section><aside class="info-stack"><section class="card pad"><div class="facility-icon">${ic(f.name==='toilet'||f.name==='upperToilet'?'toilet':f.name==='lift'||f.name==='liftUpper'?'lift':'pin')}</div><div class="flex gap" style="flex-wrap:wrap"><span class="chip green">${isUpper?t('floor1'):t('floorG')}</span>${closedFacility(chosen)?`<span class="chip red">${t('noAccess')}</span>`:`<span class="chip green">${t('available')}</span>`}</div><h3>${esc(V3_labelLoc(chosen))}</h3><p>${esc(t(f.desc))}</p><div class="feature-list"><div>${ic('wheel')} ${t('stairFree')}</div><div>${ic('info')} ${t('howTo')}</div></div>${locPending.length?`<div class="v3-inline-feature pending">${ic('clock',15)} ${locPending.length} ${t('verifyPending')}</div>`:''}${locActive.length?`<div class="alert-bubble">${ic('alert',16)} ${locActive.length} ${t('verifiedWarnings')}</div>`:''}<button class="btn btn-main btn-full" onclick="V3_goRoute('${chosen}')">${ic('route',16)} ${t('getRoute')}</button></section><section class="card pad"><h3 class="section-head">${t('floorSelect')}</h3><p class="subnote">${t('level1Tip')}</p><button class="btn btn-outline btn-full" onclick="nav('report')">${ic('flag',16)} ${t('reportProblem')}</button></section></aside></div>${footer()}`}
function V3_goRoute(id){dest=id;start=V3_qr;currentRoute=null;V3_floor=V3_LOCATION_FLOOR(id);nav('routes')}
function V3_routePage(){let x=currentRoute;const normal=V3_shortest(start,dest,false);const detour=x&&normal&&(x.units>normal.units+1);const liftUsed=x&&x.changesFloor;return `${pageHead('routeFindTitle','routeInfo')}<div class="v3-inline-feature">${ic('shield',17)} ${t('noticePending')}</div><div class="route-grid"><section class="card pad"><h2 class="section-head">${t('routeFindTitle')}</h2><p class="subnote" style="margin-bottom:23px">${t('routePref')}</p><div class="form-group"><label class="form-label" for="from">${t('start')}</label><select id="from" class="form-control" onchange="start=this.value;currentRoute=null;render()">${V3_facilityOptions(start)}</select></div><div class="form-group"><label class="form-label" for="to">${t('destination')}</label><select id="to" class="form-control" onchange="dest=this.value;currentRoute=null;render()">${V3_facilityOptions(dest)}</select></div><div class="accessible-pill">${ic('wheel')} ${t('avoid')}</div><div id="route-error" class="tiny-note" aria-live="polite" style="color:#aa5849;margin-bottom:8px"></div><button class="btn btn-main btn-full" onclick="findRoute()">${ic('route',16)} ${t('calculate')}</button>${x?`<div class="route-result"><div class="route-result-head">${t('routeFound')} ${ic('check')}</div><div class="route-big">~${x.distance} m <small>· ~${x.minutes} ${t('mins')}</small></div><p>${t('previewOnly')} · ${esc(V3_labelLoc(start))} → ${esc(V3_labelLoc(dest))}</p>${detour?`<div class="alert-bubble">${ic('alert')} ${t('detour')}</div>`:''}</div><ol class="steps-list"><li><b>1</b>${t('startAt')} ${esc(V3_labelLoc(start))}</li><li><b>2</b>${t('followRoute')}</li>${liftUsed?`<li><b>↕</b>${t(V3_LOCATION_FLOOR(dest)==='L1'?'upLift':'downLift')}</li>`:''}<li><b>3</b>${t('arriveAt')} ${esc(V3_labelLoc(dest))}</li></ol>`:`<div class="route-empty">${ic('route')} ${t('selectPrompt')}</div>`}<p class="tiny-note">${t('routeNoteLift')}</p></section><section class="card map-panel"><div class="map-toolbar">${V3_floorButtons()}<span class="chip green">${ic('wheel',13)} ${t('stairFree')}</span></div>${V3_floorMap(V3_floor,x,false)}<div class="legend"><span><i class="route"></i>${t('greenLine')}</span><span><i class="hazard"></i>${t('confirmedClosure')}</span></div>${V3_blockedEdges().size?`<div class="alert-bubble">${ic('alert')} ${t('verifiedWarnings')}: ${V3_blockedEdges().size}</div>`:''}<p class="small-hint">${ic('info',14)} ${t('notVerified')}</p></section></div>${footer()}`}
function V3_submitIssue(e){e.preventDefault();const type=document.getElementById('issue-type').value,loc=document.getElementById('issue-location').value,urgency=document.getElementById('issue-priority').value,details=document.getElementById('issue-description').value.trim();if(!type||!loc||details.length<10)return;const id='EA-'+String(Date.now()).slice(-8);const suggestion=EA_assessUrgency(type,loc);const record={id,category:type,loc,urgency,suggestedUrgency:suggestion.level,urgencyReasonCode:suggestion.reason,urgencyUserOverride:urgency!==suggestion.level,urgencyConfirmed:false,details,status:'New',verification:'pending',team:'Unassigned',notes:'',photo:picture,created:V3_now(),updated:V3_now(),history:[V3_event('timelineSubmitted','Attendee',details)]};reports.unshift(record);const ok=V3_store();if(!ok)showToast(t('cannotSavePhoto'));picture='';lastReport=id;V3_trackOpen=id;currentRoute=null;V3_floor=V3_LOCATION_FLOOR(loc);render();showToast(t('submittedV3'));window.scrollTo(0,0)}
submitIssue=V3_submitIssue;
function V3_trackCard(r,compact=false){const when=r.updated&&Date.parse(r.updated)?new Date(r.updated).toLocaleString(language==='ms'?'ms-MY':'en-MY'):(r.updated||'—');return `<div class="v3-ticket card ${compact?'compact':''}"><div class="flex between gap" style="flex-wrap:wrap"><div><span class="report-id">${esc(r.id)}</span><h3>${esc(labelCategory(r.category))}</h3><p class="subnote">${esc(V3_labelLoc(r.loc))} · ${esc(t(r.urgency||'medium'))}</p></div><div class="v3-chip-stack">${V3_statusChip(r.status)} ${V3_verificationChip(r)}</div></div><p class="v3-ticket-excerpt">${esc(r.details)}</p><div class="flex between gap"><span class="tiny-note">${esc(when)}</span><button class="table-btn" onclick="V3_viewTracking('${r.id}')">${ic('list',14)} ${t('track')}</button></div></div>`}
function V3_timeline(r){return (r.history||[]).map((ev,i)=>`<div class="v3-event"><span class="v3-event-dot ${i===r.history.length-1?'latest':''}"></span><div><strong>${esc(t(ev.type))}</strong><p>${esc(ev.actor)} · ${esc(ev.notes||'')}</p><small>${Number.isFinite(Date.parse(ev.at))?new Date(ev.at).toLocaleString(language==='ms'?'ms-MY':'en-MY'):esc(ev.at)}</small></div></div>`).join('')||`<p class="subnote">${t('timelineEmpty')}</p>`}
function V3_viewTracking(id){V3_trackOpen=id;const r=reports.find(item=>item.id===id);if(!r)return;modal(`<div class="modal-head"><div><div class="kicker">${t('ticketReference')} ${esc(r.id)}</div><h3>${t('trackTitle')}</h3></div><button class="close-btn" onclick="closeModal()" aria-label="${t('close')}">${ic('close')}</button></div><div class="flex between gap" style="flex-wrap:wrap">${V3_statusChip(r.status)} ${V3_verificationChip(r)}</div><p class="modal-desc" style="margin:15px 0"><b>${esc(labelCategory(r.category))}</b> · ${esc(V3_labelLoc(r.loc))}</p><h4 class="section-head">${t('trackSteps')}</h4><div class="v3-timeline">${V3_timeline(r)}</div><p class="tiny-note">${t('timelineNote')}</p><div class="modal-actions"><button class="btn btn-main" onclick="closeModal()">${t('close')}</button></div>`)}
openTrack=V3_viewTracking;
function V3_trackingPage(){return `${pageHead('trackTitle','trackSub')}<div class="banner">${ic('info')} ${t('oneBrowser')}. ${t('timelineNote')}</div><div class="v3-tracker-grid">${reports.length?reports.map(r=>V3_trackCard(r)).join(''):`<div class="card pad empty">${t('noReports')}</div>`}</div>${footer()}`}
function V3_dashboard(){let pending=reports.filter(r=>r.verification==='pending'&&r.status!=='Resolved'),ready=reports.filter(r=>r.status==='Ready for review'),confirmed=V3_activeVerified();let filtered=V3_annFilter==='all'?reports:V3_annFilter==='pending'?pending:V3_annFilter==='verified'?confirmed:V3_annFilter==='ready'?ready:reports.filter(r=>r.status==='Resolved');filtered=[...filtered].sort((a,b)=>EA_activeRank(b)-EA_activeRank(a) || EA_urgencyRank(b.urgency)-EA_urgencyRank(a) || (Date.parse(b.created)||0)-(Date.parse(a.created)||0));return `${pageHead('dashboardTitleV3','dashboardSubV3')}<div class="banner">${ic('shield')} ${t('roleExplain')}. ${t('reviewHint')}</div><div class="dash-metrics">${metric('list',reports.length,'total')}${metric('clock',pending.length,'pendingCard','orange')}${metric('shield',confirmed.length,'verifiedCard','blue')}${metric('check',ready.length,'readyCard','purple')}</div><div class="dash-layout"><section class="card" style="overflow:hidden"><div class="pad flex between gap" style="flex-wrap:wrap"><div><h2 class="section-head">${t('reports')}</h2><p class="subnote">${t('reportsSub')}</p></div><div class="filter-combo">${[['all','all'],['pending','pendingCard'],['verified','verifiedCard'],['ready','readyCard'],['resolved','resolved']].map(([key,label])=>`<button class="filter-button ${V3_annFilter===key?'active':''}" onclick="V3_filterDashboard('${key}')">${t(label)}</button>`).join('')}</div></div><div class="table-wrap"><table class="issue-table"><thead><tr><th>${t('issue')}</th><th>${t('location')}</th><th>${t('verifyLabel')}</th><th>${t('status')}</th><th>${t('action')}</th></tr></thead><tbody>${filtered.map(r=>`<tr><td><span class="report-id">${esc(r.id)}</span><strong>${esc(labelCategory(r.category))}</strong><div class="tiny-note">${esc(t(r.urgency||'medium'))}</div></td><td>${esc(V3_labelLoc(r.loc))}</td><td>${V3_verificationChip(r)}</td><td>${V3_statusChip(r.status)}</td><td><button class="table-btn" onclick="V3_review('${r.id}')">${t('openReview')} ${ic('arrow',13)}</button></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">${t('empty')}</div></td></tr>`}</tbody></table></div></section><aside class="card pad"><h3 class="section-head">${t('reviewTitle')}</h3><p class="subnote">${t('reviewHint')}</p><div class="v3-process"><div><span>01</span>${t('timelineSubmitted')}</div><div><span>02</span>${t('timelineVerified')}</div><div><span>03</span>${t('timelineAssigned')}</div><div><span>04</span>${t('timelineCompleted')}</div><div><span>05</span>${t('timelineResolved')}</div></div><div class="dash-cta"><b>${t('tryJourney')}</b><p>${t('roleSwitchHint')}</p><button class="btn btn-main" onclick="V3_changeRole('attendee');nav('report')">${t('createReport')} ${ic('arrow',13)}</button></div><button class="btn btn-outline btn-full" style="margin-top:14px" onclick="V3_reset()">${ic('refresh')} ${t('resetV3')}</button></aside></div>${footer()}`}
function V3_filterDashboard(x){V3_annFilter=x;render()}
function V3_review(id){const r=reports.find(x=>x.id===id);if(!r)return;selectedTicket=id;const verified=r.verification==='verified',pending=r.verification==='pending',ready=r.status==='Ready for review';modal(`<div class="modal-head"><div><div class="kicker">${t('ticketReference')}: ${esc(r.id)}</div><h3>${t('reviewTitle')}</h3></div><button class="close-btn" onclick="closeModal()" aria-label="${t('close')}">${ic('close')}</button></div><div class="flex gap" style="flex-wrap:wrap;margin-bottom:15px">${V3_statusChip(r.status)}${V3_verificationChip(r)}</div><p class="modal-desc"><b>${esc(labelCategory(r.category))}</b> · ${esc(V3_labelLoc(r.loc))} · ${esc(t(r.urgency||'medium'))}</p><div class="muted-box" style="margin-bottom:13px">${esc(r.details)}</div>${r.photo?`<div class="form-group"><span class="form-label">${t('staffPhoto')}</span><img alt="Illustrative evidence submitted locally" class="preview-img" src="${r.photo}"/></div>`:''}${pending?`<div class="banner">${ic('alert',16)} ${t('reviewHint')}</div><div class="form-group"><label class="form-label" for="v3-review-note">${t('actionNote')}</label><textarea class="form-control textarea" id="v3-review-note" maxlength="350" placeholder="Review the report and confirm against an on-site check (simulated)."></textarea></div><div class="modal-actions" style="flex-wrap:wrap;justify-content:space-between"><button class="btn btn-danger" onclick="V3_verifyDecision('rejected')">${ic('close',15)} ${t('reject')}</button><button class="btn btn-main" onclick="V3_verifyDecision('verified')">${ic('shield',15)} ${t('approve')}</button></div>`:
 verified?`<div class="form-group"><label class="form-label" for="v3-assign">${t('assign')}</label><select id="v3-assign" class="form-control">${teams.map(team=>`<option value="${team}" ${r.team===team?'selected':''}>${team}</option>`).join('')}</select></div><div class="form-group"><label class="form-label" for="v3-review-note">${t('actionNote')}</label><textarea class="form-control textarea" maxlength="350" id="v3-review-note">${esc(r.notes||'')}</textarea></div><div class="banner ${ready?'success':''}">${ic(ready?'check':'info')} ${ready?t('resolveHint'):t('organiserMustClose')}</div><div class="modal-actions" style="flex-wrap:wrap"><button class="btn btn-outline" onclick="V3_assign()">${t('assignSave')}</button>${ready?`<button class="btn btn-main" onclick="V3_confirmResolved()">${ic('check')} ${t('resolve')}</button>`:''}</div>`:
 `<p class="subnote">${r.verification==='rejected'?t('verifyRejected'):t('resolved')}</p>`}
 <hr class="v3-hr"/><h4 class="section-head">${t('trackSteps')}</h4><div class="v3-timeline">${V3_timeline(r)}</div>`)}
function V3_verifyDecision(decision){const r=reports.find(x=>x.id===selectedTicket);if(!r||r.verification!=='pending')return;const note=document.getElementById('v3-review-note').value.trim();r.verification=decision;if(decision==='rejected')r.status='Rejected';r.history.push(V3_event(decision==='verified'?'timelineVerified':'timelineRejected','Organiser',note|| (decision==='verified'?'Demo on-site review confirmed the issue.':'Demo report not verified.')));r.updated=V3_now();V3_store();currentRoute=null;const id=r.id;closeModal();render();showToast(t(decision==='verified'?'verifiedSuccess':'rejectedSuccess'));V3_review(id)}
function V3_assign(){const r=reports.find(x=>x.id===selectedTicket);if(!r||r.verification!=='verified')return;let team=document.getElementById('v3-assign').value,note=document.getElementById('v3-review-note').value.trim();if(team==='Unassigned'){showToast(t('needTeam'));return}if(r.team!==team)r.history.push(V3_event('timelineAssigned','Organiser',team));r.team=team;r.notes=note;r.updated=V3_now();V3_store();const id=r.id;closeModal();render();showToast(t('assignSave'));V3_review(id)}
function V3_confirmResolved(){const r=reports.find(x=>x.id===selectedTicket);if(!r||r.verification!=='verified'||r.status!=='Ready for review')return;r.status='Resolved';r.notes=(document.getElementById('v3-review-note')?.value||r.notes||'').trim();r.history.push(V3_event('timelineResolved','Organiser',r.notes||'Verified accessible route/facility reopened (demo).'));r.updated=V3_now();V3_store();currentRoute=null;closeModal();render();showToast(t('resolve'))}
function V3_tasksPage(){const tasks=reports.filter(r=>r.verification==='verified'&&r.team===V3_team&&r.status!=='Resolved'&&r.status!=='Rejected');return `${pageHead('staffTitle','staffSubtitle')}<div class="banner">${ic('shield')} ${t('roleExplain')}. ${t('staffExplain')}</div><div class="v3-staff-head card pad"><div><label class="form-label" for="v3-staff-team">${t('staffTeam')}</label><select class="form-control" id="v3-staff-team" onchange="V3_setTeam(this.value)">${teams.filter(x=>x!=='Unassigned').map(team=>`<option ${V3_team===team?'selected':''}>${team}</option>`).join('')}</select></div><div class="v3-staff-count"><strong>${tasks.length}</strong><span>${t('staffBoard')}</span></div></div><div class="v3-task-grid">${tasks.map(r=>`<section class="card pad"><div class="flex between gap" style="flex-wrap:wrap"><span class="report-id">${esc(r.id)}</span>${V3_statusChip(r.status)}</div><h3 class="section-head">${esc(labelCategory(r.category))}</h3><p class="subnote">${esc(V3_labelLoc(r.loc))} · ${esc(t(r.urgency||'medium'))}</p><p class="v3-ticket-excerpt">${esc(r.details)}</p><button class="btn btn-main" onclick="V3_staffWork('${r.id}')">${ic('flag',15)} ${t('openTicket')}</button></section>`).join('')||`<div class="card empty">${t('staffNoTask')}</div>`}</div>${footer()}`}
function V3_setTeam(team){if(!teams.includes(team))return;V3_team=team;savePreference('ea3_team',team);render()}
function V3_staffWork(id){const r=reports.find(x=>x.id===id);if(!r||r.team!==V3_team||r.verification!=='verified'||r.status==='Resolved')return;selectedTicket=id;modal(`<div class="modal-head"><div><div class="kicker">${esc(id)} · ${esc(V3_team)}</div><h3>${t('staffTitle')}</h3></div><button class="close-btn" onclick="closeModal()" aria-label="${t('close')}">${ic('close')}</button></div><div class="flex gap" style="flex-wrap:wrap;margin-bottom:15px">${V3_statusChip(r.status)}${V3_verificationChip(r)}</div><p class="modal-desc"><b>${esc(labelCategory(r.category))}</b> · ${esc(V3_labelLoc(r.loc))}</p><div class="muted-box">${esc(r.details)}</div><div class="form-group" style="margin-top:16px"><label class="form-label" for="v3-work-note">${t('finishNote')}</label><textarea id="v3-work-note" class="form-control textarea" maxlength="350" placeholder="Action carried out on site (simulated) ...">${esc(r.notes||'')}</textarea></div><div class="banner">${ic('info')} ${t('organiserMustClose')}</div><div class="modal-actions">${r.status==='New'?`<button class="btn btn-main" onclick="V3_staffAction('start')">${t('startWork')}</button>`:''}${r.status==='In progress'?`<button class="btn btn-main" onclick="V3_staffAction('completed')">${t('finishWork')}</button>`:''}${r.status==='Ready for review'?`<span class="chip blue">${t('staffReady')}</span>`:''}</div>`)}
function V3_staffAction(action){const r=reports.find(x=>x.id===selectedTicket);if(!r||r.team!==V3_team||r.verification!=='verified')return;const note=document.getElementById('v3-work-note').value.trim();if(action==='start'&&r.status==='New'){r.status='In progress';r.history.push(V3_event('timelineStarted','Staff · '+V3_team,note||'Work started in demo.'))}else if(action==='completed'&&r.status==='In progress'){if(note.length<8){showToast(t('finishNote')+' — minimum 8 characters');return}r.status='Ready for review';r.history.push(V3_event('timelineCompleted','Staff · '+V3_team,note))}else return;r.notes=note;r.updated=V3_now();V3_store();const id=r.id;closeModal();render();showToast(t(action==='start'?'startWork':'staffReady'));V3_staffWork(id)}
function V3_stats(){const statuses=[['New','newStatus'],['In progress','progress'],['Ready for review','readyStatus'],['Resolved','resolved'],['Rejected','rejectedStatus']];const countBy=key=>[...new Set(reports.map(r=>r[key]))].map(x=>({label:key==='category'?t(x):V3_labelLoc(x),count:reports.filter(r=>r[key]===x).length})).sort((a,b)=>b.count-a.count);return{statuses:statuses.map(([status,label])=>({label:t(label),count:reports.filter(r=>r.status===status).length})),categories:countBy('category'),locations:countBy('loc'),pending:reports.filter(r=>r.verification==='pending').length,verified:reports.filter(r=>r.verification==='verified').length,rejected:reports.filter(r=>r.verification==='rejected').length,resolved:reports.filter(r=>r.status==='Resolved').length,mean:reports.filter(r=>r.status==='Resolved'&&Date.parse(r.created)&&Date.parse(r.updated)).reduce((a,r,i,all)=>a+(Date.parse(r.updated)-Date.parse(r.created))/60000/all.length,0)}}
function V3_barChart(items){const max=Math.max(1,...items.map(x=>x.count));return `<div class="v3-bars">${items.map((x,i)=>`<div class="v3-bar-row"><span>${esc(x.label)}</span><div class="v3-bar-track"><div class="v3-bar-fill v3-color-${i%4}" style="width:${Math.round(x.count/max*100)}%"></div></div><strong>${x.count}</strong></div>`).join('')||`<p class="subnote">${t('empty')}</p>`}</div>`}
function V3_analyticsPage(){const d=V3_stats();const rate=reports.length?Math.round(d.resolved/reports.length*100):0;return `${pageHead('analyticsTitle','analyticsSub')}<div class="banner">${ic('info')} ${t('demoBanner')} ${t('medianNote')}</div><div class="dash-metrics">${metric('list',reports.length,'tally')}${metric('clock',d.pending,'pendingCard','orange')}${metric('shield',d.verified,'verifiedCard','blue')}${metric('check',rate+'%','resolutionRate','purple')}</div><div class="v3-analytics-grid"><section class="card pad"><h2 class="section-head">${t('statusBreakdown')}</h2><p class="subnote">${t('oneBrowser')}</p>${V3_barChart(d.statuses)}</section><section class="card pad"><h2 class="section-head">${t('issueBreakdown')}</h2><p class="subnote">${t('issueType')}</p>${V3_barChart(d.categories)}</section><section class="card pad"><h2 class="section-head">${t('topAreas')}</h2><p class="subnote">${t('location')}</p>${V3_barChart(d.locations.slice(0,6))}</section><section class="card pad"><h2 class="section-head">${t('approvalStats')}</h2><div class="v3-stat-row"><span>${t('verifyPending')}</span><strong>${d.pending}</strong></div><div class="v3-stat-row"><span>${t('verifyApproved')}</span><strong>${d.verified}</strong></div><div class="v3-stat-row"><span>${t('verifyRejected')}</span><strong>${d.rejected}</strong></div><hr class="v3-hr"/><h3 class="section-head">${t('averageResolution')}</h3><div class="v3-average">${d.mean>0?Math.round(d.mean)+' '+t('mins'):'—'}</div><p class="small-hint">${t('medianNote')}</p></section></div>${footer()}`}
function V3_home(){const n=reports.length,verified=V3_activeVerified().length,pending=reports.filter(r=>r.verification==='pending').length;return `${pageHead('homeTitle','homeSubtitle')}<section class="hero"><div class="hero-copy"><div class="hero-kicker">${t('heroV3')}</div><h2>${t('hero3Title')}</h2><p>${t('hero3Text')}</p><div class="hero-actions"><button class="btn btn-main" onclick="nav('map')">${t('explore')} ${ic('arrow',16)}</button><button class="btn btn-outline" onclick="nav('routes')">${t('findRoute')} ${ic('route',16)}</button></div></div><div class="hero-map"><div class="hero-graphic"><svg class="hero-route" viewBox="0 0 290 200" aria-hidden="true"><rect x="24" y="21" width="95" height="73" rx="13" fill="#d2e5dc"/><rect x="136" y="21" width="125" height="73" rx="13" fill="#d3e8df"/><rect x="24" y="109" width="95" height="70" rx="13" fill="#d2e5dc"/><rect x="136" y="109" width="125" height="70" rx="13" fill="#d2e5dc"/><path d="M74 144H144V58H213" fill="none" stroke="#079980" stroke-width="10" stroke-linecap="round" stroke-dasharray="14 10"/><circle cx="74" cy="144" r="12" fill="#087965" stroke="white" stroke-width="5"/><circle cx="213" cy="58" r="12" fill="#087965" stroke="white" stroke-width="5"/><text x="44" y="62" fill="#62827d" font-size="12" font-weight="900">EVENT HALL</text></svg><div class="hero-overlay">${ic('check',15)} ${t('stairFree')}</div></div></div></section><div class="home-metrics">${metric('pin',Object.keys(facility).length,'mapped')}${metric('list',n,'total','blue')}${metric('clock',pending,'pendingCard','orange')}${metric('shield',verified,'verifiedCard','purple')}</div><div class="home-grid"><section class="card pad"><div class="flex between gap"><div><h2 class="section-head">${t('demoUpgrade')}</h2><p class="subnote">${t('originalNote')}</p></div><button class="btn btn-outline" onclick="openQr()">${ic('qr',15)} ${t('qrConcept')}</button></div><div class="step-grid"><div class="step"><span class="step-index">01</span><h3>${t('quickVerification')}</h3><p>${t('noticePending')}</p></div><div class="step"><span class="step-index">02</span><h3>${t('quickRouting')}</h3><p>${t('routeNoteLift')}</p></div><div class="step"><span class="step-index">03</span><h3>${t('quickStaff')}</h3><p>${t('organiserMustClose')}</p></div></div></section><section class="card pad"><h3 class="section-head">${t('roleExplain')}</h3><p class="subnote">${t('roleSwitchHint')}</p><div class="v3-role-summary"><button class="btn btn-outline" onclick="V3_changeRole('attendee');nav('report')">${t('roleAttendee')}</button><button class="btn btn-outline" onclick="V3_changeRole('organiser');nav('dashboard')">${t('roleOrganiser')}</button><button class="btn btn-outline" onclick="V3_changeRole('staff');nav('tasks')">${t('roleStaff')}</button></div><div class="v3-inline-feature" style="margin-top:16px">${ic('shield',17)} ${t('demoBanner')}</div></section></div>${footer()}`}
function V3_changeRole(role){if(!V3_ROLE.includes(role))return;V3_role=role;savePreference('ea3_role',role);const link=location.hash.slice(1)||'home';if(!V3_MENU[role].some(i=>i[0]===link))location.hash='#home';render()}
function V3_reset(){if(!confirm(t('confirmReset')))return;reports=structuredClone(V3_SEEDS);V3_store();lastReport=null;currentRoute=null;V3_annFilter='all';render();showToast(t('resetV3'))}
resetDemo=V3_reset;
function V3_render(){let page=location.hash.slice(1).split('?')[0]||'home';const m=V3_MENU[V3_role];if(!m.some(item=>item[0]===page))page='home';document.documentElement.lang=language==='ms'?'ms':'en';document.getElementById('nav-links').innerHTML=m.map(([id,label,sym])=>`<button class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''} onclick="nav('${id}')">${ic(sym)}<span>${t(label)}</span></button>`).join('');document.getElementById('crumb-name').textContent=t(m.find(v=>v[0]===page)[1]);document.querySelector('[data-t="sidebarHelpTitle"]').textContent=t('sidebarHelpTitle');document.querySelector('[data-t="sidebarHelpText"]').textContent=t('sidebarHelpText');document.getElementById('sidebar-help-btn').innerHTML=t('sidebarButton')+' <span>↗</span>';document.getElementById('lang-button').textContent=language==='en'?'BM':'EN';document.getElementById('role-picker').value=V3_role;document.getElementById('view').innerHTML=({home:V3_home,map:V3_map,routes:V3_routePage,report:reportPage,track:V3_trackingPage,dashboard:V3_dashboard,analytics:V3_analyticsPage,tasks:V3_tasksPage})[page]();document.title='EventAccess V3 · '+t(m.find(v=>v[0]===page)[1]);}
render=V3_render;
function V3_findRoute(){if(start===dest){document.getElementById('route-error').textContent=t('samePlace');return}currentRoute=V3_shortest(start,dest,true);if(currentRoute)V3_floor=V3_LOCATION_FLOOR(start);render();if(!currentRoute){document.getElementById('route-error').textContent=t('noRouteAsk');showToast(t('noRouteAsk'))}}
findRoute=V3_findRoute;
function V3_startQr(){V3_qr=qrChoice;chosen=qrChoice;start=qrChoice;dest='toilet';V3_floor=V3_LOCATION_FLOOR(qrChoice);closeModal();nav('map');showToast(t('qrFloor')+' · '+V3_labelLoc(V3_qr))}
startQrJourney=V3_startQr;
// replace V2 report-form location list including all upper-floor places
const V3_reportBase=reportPage;
reportPage=function(){return V3_reportBase().replace('></select></div></div><div class="form-group"><label for="issue-priority"','></select></div></div><div class="form-group"><label for="issue-priority"');};
// Reuse V2 reportPage, whose options now reflect the V3 facilities and the report submit override.
// The initial report is never considered a verified closure.
document.getElementById('role-picker').addEventListener('change',e=>V3_changeRole(e.target.value));
// Dismiss any V2 pages left in local storage with an explicit separate V3 namespace.
render();
